#!/usr/bin/env python3
"""Generate harness/run_tests.mcfunction from the test functions in a tests pack.

Every .mcfunction under data/elemental_tools_test/function/ is a test, except the
ones in the `harness/` and `assert/` folders. Adding a test file is all it takes
to get it run: there is no list to maintain.

Usage:
  generate_test_runner.py [tests_pack_dir]     (default: tests)
"""

from __future__ import annotations

import sys
from pathlib import Path

NAMESPACE = "elemental_tools_test"
NON_TEST_FOLDERS = {"harness", "assert"}
# Where the test functions run: the arena test position (see harness/run).
TEST_POSITION = "8 150 8"


def find_tests(pack_dir: Path) -> list[str]:
    function_dir = pack_dir / "data" / NAMESPACE / "function"
    tests = []
    for path in sorted(function_dir.rglob("*.mcfunction")):
        relative = path.relative_to(function_dir).with_suffix("")
        if relative.parts[0] in NON_TEST_FOLDERS:
            continue
        tests.append(relative.as_posix())
    return tests


def render(tests: list[str]) -> str:
    lines = [
        "## GENERATED by .github/scripts/generate_test_runner.py. Do not edit by hand.",
        f"## Runs each of the {len(tests)} test functions in this pack, one after the other.",
        "",
    ]
    for test in tests:
        lines += [
            f'data modify storage et_test:run name set value "{test}"',
            f"function {NAMESPACE}:harness/begin_test",
            f"execute positioned {TEST_POSITION} run function {NAMESPACE}:{test}",
            f"function {NAMESPACE}:harness/end_test",
            "",
        ]
    return "\n".join(lines)


def generate(pack_dir: Path) -> int:
    tests = find_tests(pack_dir)
    if not tests:
        raise SystemExit(f"No test functions found under {pack_dir}")
    target = pack_dir / "data" / NAMESPACE / "function" / "harness" / "run_tests.mcfunction"
    target.write_text(render(tests), encoding="utf-8", newline="\n")
    return len(tests)


if __name__ == "__main__":
    pack = Path(sys.argv[1] if len(sys.argv) > 1 else "tests")
    print(f"Generated {pack}: {generate(pack)} tests")